mapper.select:
SELECT

FROM risk_assessment_detail


        assessment_id = #{param.assessmentId}


        AND risk_category = #{param.riskCategory}


        AND risk_item LIKE CONCAT('%', #{param.riskItem}, '%')


        AND risk_level = #{param.riskLevel}


        AND risk_status = #{param.riskStatus}


        AND mitigation_status = #{param.mitigationStatus}


        AND responsible_person LIKE CONCAT('%', #{param.responsiblePerson}, '%')


        AND risk_score >= #{param.minRiskScore}


        AND risk_score <= #{param.maxRiskScore}


ORDER BY risk_score DESC, create_time DESC

SELECT

FROM risk_assessment_detail

    risk_level >= #{minRiskLevel}
    AND risk_status = 1

        AND assessment_id = #{assessmentId}


ORDER BY risk_score DESC

SELECT risk_category, COUNT(*) as count, AVG(risk_score) as avgRiskScore, AVG(residual_risk_score) as avgResidualRiskScore, SUM(CASE WHEN risk_level >= 3 THEN 1 ELSE 0 END) as highRiskCount, SUM(CASE WHEN risk_status = 1 THEN 1 ELSE 0 END) as activeCount FROM risk_assessment_detail
assessment_id = #{assessmentId}
GROUP BY risk_category ORDER BY avgRiskScore DESC

SELECT DATE_FORMAT(create_time, '%Y-%m') as month, COUNT(*) as totalRisks, AVG(risk_score) as avgRiskScore, SUM(CASE WHEN risk_level >= 3 THEN 1 ELSE 0 END) as highRiskCount, SUM(CASE WHEN risk_status = 3 THEN 1 ELSE 0 END) as closedRiskCount FROM risk_assessment_detail
assessment_id = #{assessmentId}
AND create_time >= #{startDate}
AND create_time <= #{endDate}
GROUP BY DATE_FORMAT(create_time, '%Y-%m') ORDER BY month DESC LIMIT 12
